43	  const { data: userStats, isLoading: isLoadingUserStats } = useUserStats(userName);
44	  // explore/archived: fetch backend grouped stats and aggregate them locally.
45	  // ListAllUserStats AND's the request filter with the server's auth filter, so
46	  // private memos are not included unless explicitly visible to the current user.
47	  const exploreVisibilityFilter = currentUser != null ? 'visibility in ["PUBLIC", "PROTECTED"]' : 'visibility in ["PUBLIC"]';
48	  const allUserStatsRequest =
49	    context === "explore"
50	      ? { state: State.NORMAL, filter: exploreVisibilityFilter }
51	      : context === "archived"
52	        ? { state: State.ARCHIVED }
53	        : {};
